import json,re,unicodedata,collections
rows=json.load(open('.latest_query.json'))
def norm(n):
    n=n.split(' - ')[0]
    n=unicodedata.normalize('NFKD',n).encode('ascii','ignore').decode().upper()
    n=re.sub(r'[^A-Z ]',' ',n)
    return ' '.join(n.split())
by=collections.defaultdict(dict)
for r in rows:
    by[r['nome_do_campus']][norm(r['nome_da_unidade'])]=r['nome_da_unidade']
cg=by['CAMPINA GRANDE']
outros={}
for c,d in by.items():
    if c!='CAMPINA GRANDE':
        for k,v in d.items(): outros.setdefault(k,[]).append(c)
print('--- CG sem correspondente (nome normalizado) ---')
for k in sorted(cg):
    if k not in outros: print(' ',cg[k])
print(len([k for k in cg if k not in outros]),'de',len(cg))
print('--- CG com correspondente ---')
for k in sorted(cg):
    if k in outros: print(' ',cg[k],'->',sorted(set(outros[k])))
"

