import json,re,unicodedata
def norm(s):
    s=unicodedata.normalize('NFKD',s or '').encode('ascii','ignore').decode().upper()
    return re.sub(r'\s+',' ',s).split(' - ')[0].strip()
cg=json.load(open('/workspace/cg.json'))
out=json.load(open('/workspace/outros.json'))
oset={}
for o in out: oset.setdefault(norm(o['nome_da_unidade']),[]).append(o['nome_do_campus'])
print('=== CG com equivalente ===')
for u in cg:
    n=norm(u['nome_da_unidade'])
    if n in oset: print(n,'->',oset[n])
print()
print('=== todos CG (28) ===')
for i,u in enumerate(sorted(cg,key=lambda x:x['nome_da_unidade']),1): print(i,u['nome_da_unidade'])
