    s=unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().upper().strip()
    return ' '.join(s.split())
cg=[r for r in d if r['nome_do_campus']=='CAMPINA GRANDE']
outros=[r for r in d if r['nome_do_campus']!='CAMPINA GRANDE']
nomes_outros={norm(r['nome_da_unidade']) for r in outros}
locais=defaultdict(list)
for r in outros: locais[norm(r['nome_da_unidade'])].append(r['nome_do_campus'])
print('--- CG units NOT present in other campuses ---')
for r in sorted(cg, key=lambda x: norm(x['nome_da_unidade'])):
    if norm(r['nome_da_unidade']) not in nomes_outros:
        print(' *', r['nome_da_unidade'], '|', r['sigla_da_unidade'], '|', r['nome_do_centro'])
print()
print('--- CG units ALSO found in other campuses ---')
for r in sorted(cg, key=lambda x: norm(x['nome_da_unidade'])):
    if norm(r['nome_da_unidade']) in nomes_outros:
        print(' -', r['nome_da_unidade'],'->',sorted(set(locais[norm(r['nome_da_unidade'])])))
